h.css:
:root{
  --bg:#f6f8fb; --card:#fff; --line:#e3e8f0; --ink:#1c2533; --ink2:#4a5567;
  --ink3:#8b95a7; --brand:#1f6feb; --brand-bg:#eef5ff; --accent:#0f9d8f;
  --amber:#b26a00; --amber-bg:#fff6e6;
}
*{box-sizing:border-box}
body{
  margin:0; background:var(--bg); color:var(--ink);
  font:15px/1.78 -apple-system,"Segoe UI","Microsoft YaHei",sans-serif;
}
.wrap{max-width:980px; margin:0 auto; padding:34px 26px 70px}
.doc{background:var(--card); border:1px solid var(--line); border-radius:14px;
     padding:38px 44px 46px; box-shadow:0 1px 3px rgba(16,31,55,.05)}
h1{font-size:25px; line-height:1.35; margin:0 0 6px; letter-spacing:.2px}
h1 + p, h1 + blockquote{margin-top:0}
h2{font-size:19px; margin:34px 0 12px; padding-bottom:8px;
   border-bottom:2px solid var(--brand); color:#12325e}
h3{font-size:16.5px; margin:24px 0 9px; color:#183457}
h4{font-size:15px; margin:18px 0 7px; color:var(--accent)}
p{margin:9px 0}
a{color:var(--brand); text-decoration:none; border-bottom:1px solid #bcd4f7}
a:hover{background:var(--brand-bg)}
strong{color:#0f2744}
code{background:#f0f3f8; border:1px solid #e0e6ef; border-radius:4px;
     padding:1px 5px; font-size:12.5px; font-family:Consolas,"Courier New",monospace;
     color:#9a3b3b; word-break:break-word}
blockquote{margin:14px 0; padding:12px 16px; background:var(--brand-bg);
           border-left:4px solid var(--brand); border-radius:0 8px 8px 0; color:var(--ink2)}
blockquote p{margin:5px 0}
blockquote strong{color:#12325e}
ul,ol{margin:9px 0; padding-left:24px}
li{margin:4px 0}
hr{border:0; border-top:1px dashed var(--line); margin:26px 0}
table{border-collapse:collapse; width:100%; margin:14px 0; font-size:13.5px;
      display:block; overflow-x:auto}
th,td{border:1px solid var(--line); padding:8px 11px; text-align:left; vertical-align:top}
th{background:#f2f6fc; color:#1a3355; font-weight:600; white-space:nowrap}
tr:nth-child(even) td{background:#fafcff}
.toolbar{display:flex; gap:10px; align-items:center; flex-wrap:wrap;
         margin:0 0 16px; font-size:12.5px; color:var(--ink3)}
.toolbar .sp{flex:1}
.tag{background:var(--amber-bg); color:var(--amber); border:1px solid #ffe0b0;
     border-radius:20px; padding:2px 10px}
@media print{body{background:#fff} .doc{border:0; box-shadow:none; padding:0}
  .toolbar{display:none} .wrap{max-width:none; padding:0}}

